const entries = $input.first().json.feed.entry;
const entryArray = Array.isArray(entries) ? entries : [entries];

return entryArray.map((entry) => ({
  json: {
    paper_id: 'arxiv:' + entry.id.replace(/^https?:\/\/arxiv\.org\/abs\//, '').replace(/v\d+$/, ''),
    title: entry.title?.replace(/\s+/g, ' ').trim(),
    summary: entry.summary?.replace(/\s+/g, ' ').trim(),
    published: entry.published,
    url: entry.id,
    source: 'arXiv',
  },
}));

const TOP_PER_BATCH = 2;   // au plus 2 papiers par lot peuvent atteindre 7+

const papers = $('Nouveau papier ?').all().map(i => i.json);
const byId = Object.fromEntries(papers.map(p => [p.paper_id, p]));
const clamp = (v, max) => Math.max(0, Math.min(max, Math.round(Number(v) || 0)));
const out = [];

for (const item of $input.all()) {
  const raw = String(item.json.text || '')
    .replace(/```json|```/g, '')
    .trim()
    .replace(/,\s*([}\]])/g, '$1');
  if (!raw) continue; // échec Gemini : ce lot sera retenté la semaine suivante

  let arr;
  try { arr = JSON.parse(raw); } catch (e) { continue; }
  if (!Array.isArray(arr)) arr = [arr];

  const scored = [];
  for (const ai of arr) {
    const paper = byId[ai.paper_id];
    if (!paper) continue;
    const category = ai.category || 'Autre';
    let score = clamp(ai.relevance, 4) + clamp(ai.utility, 3) + clamp(ai.rigor, 3);
    if (category === 'Autre') score = Math.min(score, 3);
    scored.push({ paper, ai, category, score, rank: Number(ai.rank) || 99 });
  }

  // classement dans le lot : score décroissant, puis rang donné par Gemini
  scored.sort((a, b) => b.score - a.score || a.rank - b.rank);

  scored.forEach((s, idx) => {
    // seuls les meilleurs du lot peuvent atteindre 7 ou plus
    const finalScore = idx < TOP_PER_BATCH ? s.score : Math.min(s.score, 6);
    out.push({ json: {
      ...s.paper,
      score: finalScore,
      raw_score: s.score,
      rank: s.rank,
      category: s.category,
      summary_en: s.ai.summary_en || ''
    }});
  });
}
return out;

const seen = new Set();
const out = [];

// OpenAlex fournit l'abstract sous forme d'index inversé : {mot: [positions]}
function rebuild(inv) {
  const words = [];
  for (const [word, positions] of Object.entries(inv || {})) {
    for (const pos of positions) words[pos] = word;
  }
  return words.filter(Boolean).join(' ');
}

for (const item of $input.all()) {
  for (const w of item.json.results || []) {
    if (!w.title || !w.abstract_inverted_index) continue;
    if (String(w.doi || '').includes('10.48550/arxiv')) continue; // déjà couvert par arXiv

    const paper_id = `openalex:${String(w.id).replace('https://openalex.org/', '')}`;
    if (seen.has(paper_id)) continue;
    seen.add(paper_id);

    out.push({
      json: {
        paper_id,
        title: w.title,
        summary: rebuild(w.abstract_inverted_index),
        published: w.publication_date,
        url: w.doi || w.id,
        source: 'OpenAlex'
      }
    });
  }
}
return out;

const toArxiv = q => {
  const t = q.trim();
  const phrase = t.startsWith('"') && t.endsWith('"');
  const inner = phrase ? t.slice(1, -1) : t;
  const enc = encodeURIComponent(inner).replace(/%20/g, '+');
  return phrase ? `all:%22${enc}%22` : `all:${enc}`;
};

const search_query = $input.all().map(i => toArxiv(i.json.query)).join('+OR+');

const url = `https://export.arxiv.org/api/query?search_query=${search_query}&sortBy=submittedDate&sortOrder=descending&max_results=60`
  .replace(/[^\x21-\x7E]/g, '');

return [{ json: { arxivQuery: search_query, url } }];

const TOP_N = 7;           // détaillés (Telegram + email)
const MORE_MAX = 20;       // supplémentaires (email seulement, format court)
const MAX_PER_SOURCE = 4;  // diversité dans le top

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const all = $input.all().map(i => i.json)
  .sort((a, b) => b.score - a.score || (a.rank ?? 99) - (b.rank ?? 99));

// Top avec plafond par source
const top = [];
const perSource = {};
for (const p of all) {
  if (top.length >= TOP_N) break;
  const s = p.source || '?';
  if ((perSource[s] || 0) >= MAX_PER_SOURCE) continue;
  perSource[s] = (perSource[s] || 0) + 1;
  top.push(p);
}
// si le plafond a laissé des places vides, on complète
for (const p of all) {
  if (top.length >= TOP_N) break;
  if (!top.includes(p)) top.push(p);
}
const more = all.filter(p => !top.includes(p)).slice(0, MORE_MAX);
const notShown = all.length - top.length - more.length;

// Telegram (texte simple)
const telegramText = [
  `📚 Research digest: top ${top.length} papers` + (more.length ? ` (+${more.length} more in your email)` : ''),
  ...top.map((p, i) =>
    `${i + 1}. 📄 ${p.title}\n⭐ ${p.score}/10 · ${p.category} · ${p.source}\n${p.summary_en}\n🔗 ${p.url}`)
].join('\n\n').slice(0, 4000);

// Email (HTML)
const topHtml = top.map((p, i) => `
  <div style="margin-bottom:20px">
    <h3 style="margin:0">${i + 1}. <a href="${esc(p.url)}">${esc(p.title)}</a></h3>
    <div style="color:#666;font-size:13px;margin:2px 0">${esc(p.category)} · ${esc(p.score)}/10 · ${esc(p.source)}</div>
    <p style="margin:4px 0 0 0">${esc(p.summary_en)}</p>
  </div>`).join('');

const moreHtml = more.length ? `
  <h3>More worth a look (${more.length})</h3>
  <ul>${more.map(p => `<li><a href="${esc(p.url)}">${esc(p.title)}</a> — ${esc(p.score)}/10 · ${esc(p.category)} · ${esc(p.source)}</li>`).join('')}</ul>` : '';

const footer = notShown > 0 ? `<p style="color:#666">${notShown} more papers scored 7+ but are not listed.</p>` : '';

return [{
  json: {
    subject: `Research digest: ${top.length} top papers + ${more.length} more`,
    html: `<h2>Weekly Research Digest</h2>${topHtml}${moreHtml}${footer}`,
    telegramText
  }
}];

const SIZE = 8;
const papers = $input.all().map(i => i.json);
const out = [];

for (let i = 0; i < papers.length; i += SIZE) {
  const chunk = papers.slice(i, i + SIZE);
  const promptText = chunk.map(p =>
    `paper_id: ${p.paper_id}\nTitle: ${p.title}\nAbstract: ${String(p.summary || '').slice(0, 1500)}`
  ).join('\n\n---\n\n');
  out.push({ json: { promptText } });
}
return out;

const DAYS = 7;                          // fenêtre glissante, en jours
const cutoff = Date.now() - DAYS * 24 * 3600 * 1000;
const first = v => Array.isArray(v) ? v[0] : v;
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  for (const d of (item.json.response?.docs || [])) {
    const title = first(d.title_s);
    const summary = first(d.abstract_s);
    if (!title || !summary) continue;
    if (d.arxivId_s) continue;            // déjà couvert par la branche arXiv

    const dateStr = d.submittedDate_s || d.producedDate_s || '';
    const t = Date.parse(String(dateStr).replace(' ', 'T'));
    if (!isNaN(t) && t < cutoff) continue;

    const paper_id = `hal:${d.halId_s}`;
    if (seen.has(paper_id)) continue;
    seen.add(paper_id);

    out.push({ json: {
      paper_id,
      title,
      summary,
      published: dateStr,
      url: d.uri_s || `https://hal.science/${d.halId_s}`,
      source: 'HAL'
    }});
  }
}
return out;

const norm = s => String(s || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

// en cas de doublon, on garde la source la plus fiable
const priority = { arXiv: 0, OpenAlex: 1, HAL: 2 };

const items = $input.all().map(i => i.json)
  .sort((a, b) => (priority[a.source] ?? 9) - (priority[b.source] ?? 9));

const seen = new Set();
const bySource = {};
for (const p of items) {
  const key = norm(p.title);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  (bySource[p.source] ||= []).push(p);
}

// alternance entre sources : le Limit garde ainsi un melange equilibre
const lists = Object.values(bySource);
const out = [];
for (let i = 0; lists.some(l => i < l.length); i++) {
  for (const l of lists) if (i < l.length) out.push({ json: l[i] });
}
return out;
